<form method="post" enctype="multipart/form-data" action="<?= base_url('admin/news/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= esc($article['id'] ?? '') ?>"><div class="edit-grid"><section class="panel"><label>หัวข้อข่าว<input name="title" maxlength="255" required value="<?= esc($value('title')) ?>" placeholder="ระบุหัวข้อข่าวสาร"></label><label>เนื้อหาข่าว<textarea name="body" rows="17" required maxlength="100000" placeholder="เขียนรายละเอียดข่าวสาร…"><?= esc($value('body')) ?></textarea></label><p class="muted">เวอร์ชันเริ่มต้นใช้ข้อความธรรมดา รองรับการขึ้นบรรทัดใหม่</p><?= view('gallery_editor', ['article'=>$article,'value'=>$value]) ?></section><aside class="panel"><h3>การเผยแพร่</h3><label>หมวดหมู่<select name="category"><?php foreach (\App\Models\Article::CATEGORIES as $cat): ?><option <?= $value('category')===$cat?'selected':'' ?>><?= esc($cat) ?></option><?php endforeach ?></select></label><label>สถานะ<select name="status"><option value="draft" <?= $value('status')!=='published'?'selected':'' ?>>ฉบับร่าง</option><option value="published" <?= $value('status')==='published'?'selected':'' ?>>เผยแพร่</option></select></label><label>รูปปกข่าว<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><small class="muted">JPG, PNG, WebP ไม่เกิน 4 MB</small><?php if ($article['image'] ?? null): ?><img class="preview-image" src="<?= base_url('media/'.$article['image']) ?>" alt="รูปปกปัจจุบัน"><label class="checkbox"><input type="checkbox" name="remove_image" value="1"> เอารูปปกออก</label><?php endif ?><div class="pdf-upload"><label>ไฟล์ PDF ประกาศ<input type="file" name="pdf" accept="application/pdf,.pdf"></label><small class="muted">ประกาศสหกรณ์ต้องแนบ PDF ก่อนเผยแพร่ ขนาดไม่เกิน 2 MB รูปปกจะไม่แสดงในหน้าอ่านประกาศ</small><?php if ($article['pdf'] ?? null): ?><a class="back" href="<?= base_url('news/'.$article['id'].'/pdf') ?>" target="_blank" rel="noopener">เปิดไฟล์ PDF ปัจจุบัน ↗</a><label class="checkbox"><input type="checkbox" name="remove_pdf" value="1"> เอาไฟล์ PDF ออก</label><?php endif ?></div><button class="full">บันทึกข่าวสาร</button><?php if (($article['status'] ?? '')==='published'): ?><a class="back" href="<?= base_url('news/'.$article['id']) ?>" target="_blank" rel="noopener">ดูข่าวบนเว็บไซต์ ↗</a><?php endif ?></aside></div></form>
